export const BackupLabelStatus = {
  active: 'active',
  archived: 'archived',
} as const;

export interface BackupLabel {
  id: string;
  /**
     * @minLength 1
     * @maxLength 80
     */
  name: string;
  /** @pattern ^#[0-9A-Fa-f]{6}$ */
  color: string;
  status: BackupLabelStatus;
  createdAt?: string;
  updatedAt?: string;
}

export interface BackupExpense {
  id: string;
  /**
     * @maxLength 15
     * @pattern ^[0-9]{1,12}(\.[0-9]{1,2})?$
     */
  amount: string;
  date: string;
  /** @nullable */
  projectId?: string | null;
  categoryId: string;
  /**
     * @maxLength 1000
     * @nullable
     */
  description?: string | null;
  paymentMethod?: ExpensePaymentMethod | null;
  /**
     * @maxLength 4000
     * @nullable
     */
  notes?: string | null;
  /**
     * @minLength 3
     * @maxLength 3
     */
  currency: string;
  /**
     * Location slug. Optional so backups exported before locations existed still import; those rows fall back to the default location.
     * @minLength 1
     * @maxLength 80
     * @nullable
     */
  location?: string | null;
  /** Optional so backups exported before transaction types existed still import; those rows are treated as expenses. */
  transactionType?: ExpenseTransactionType | null;
  createdAt?: string;
  updatedAt?: string;
}

export interface BackupExpenseLabel {
  expenseId: string;
  labelId: string;
}

export interface BackupDocumentCounts {
  /** @minimum 0 */
  projects?: number;
  /** @minimum 0 */
  categories?: number;
  /** @minimum 0 */
  labels?: number;
  /** @minimum 0 */
  expenses?: number;
  /** @minimum 0 */
  expenseLabels?: number;
}

export type BackupDocumentFormat = typeof BackupDocumentFormat[keyof typeof BackupDocumentFormat];


export const BackupDocumentFormat = {
  'pocketful-backup': 'pocketful-backup',
} as const;

export interface BackupDocument {
  format: BackupDocumentFormat;
  /** @minimum 1 */
  version: number;
  exportedAt?: string;
  counts?: BackupDocumentCounts;
  projects: BackupProject[];
  categories: BackupCategory[];
  labels: BackupLabel[];
  expenses: BackupExpense[];
  expenseLabels: BackupExpenseLabel[];
}

export interface BackupImportCount {
  /** @minimum 0 */
  created: number;
  /** @minimum 0 */
  updated: number;
  /** @minimum 0 */
  skipped: number;
}

export interface BackupImportResult {
  projects: BackupImportCount;
  categories: BackupImportCount;
  labels: BackupImportCount;
  expenses: BackupImportCount;
  /** @minimum 0 */
  expenseLabels: number;
  warnings: string[];
}

